    @property
    def area_name(self) -> str:
        return AREA_NAMES.get(self.area, f"area {self.area}")

    @property
    def is_dimmer(self) -> bool:
        return self.area in DIMMER_AREAS

    @property
    def is_relay(self) -> bool:
        return self.area in RELAY_AREAS

    @property
    def is_panel(self) -> bool:
        return self.area in PANEL_AREAS


