def lookup(code: int) -> DeviceInfo | None:
    """Catalog entry for a bus device-type code, or None if unknown."""
    return CATALOG.get(code)


def channel_count(code: int) -> int:
    """Output channels (modules) or keys (panels) for a type; 0 if unknown."""
    info = CATALOG.get(code)
    return info.channels if info else 0
